def llm_node(
    self,
    chat_ctx: ChatContext,
    tools: list[FunctionTool | RawFunctionTool],
    model_settings: ModelSettings,
) -> (
    AsyncIterable[ChatChunk | str]
    | Coroutine[Any, Any, AsyncIterable[ChatChunk | str]]
    | Coroutine[Any, Any, str]
    | Coroutine[Any, Any, ChatChunk]
    | Coroutine[Any, Any, None]
):
    async def empty_coroutine_func() -> None:
        pass

    transfer_manager = self.session.userdata.transfer_manager
    if transfer_manager and not transfer_manager.should_allow_interaction():
        return empty_coroutine_func()

    chat_ctx = clean_chat_ctx(chat_ctx)

    last_assistant_message = None
    if len(chat_ctx.items) > 1:
        for item in reversed(chat_ctx.items[:-1]):
            if item.type == "message" and item.role == "assistant":
                last_assistant_message = item
                break
    if last_assistant_message and last_assistant_message.interrupted:
        # Let the agent know it was interrupted, so it can adapt its reply.
        logger.info(
            f"Agent was interrupted, adding (interrupted) to the last assistant message {last_assistant_message.content}",
            extra={
                "job_id": self.session.userdata.ctx.job.id,
                "room_name": self.session.userdata.ctx.job.room.name,
            },
        )
        last_assistant_message.content.append("(interrupted)")

    return Agent.default.llm_node(self, chat_ctx, tools, model_settings)

